<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { data } from '../store';
import { clone } from '../model';
import { capabilities, loadCapabilities, useExecution, savePreset, downloadJson, type CompatResult, type DeviceResult } from '../execution';
import Icon from '../components/Icon.vue';
import Modal from '../components/Modal.vue';
import EnvironmentPicker from '../components/EnvironmentPicker.vue';
import PresetBar from '../components/PresetBar.vue';
import ExecutionStatus from '../components/ExecutionStatus.vue';
import ExecutionHistory from '../components/ExecutionHistory.vue';
const devices = [
  { id: 'desktop', label: '桌面', width: 1440, height: 900 }, { id: 'laptop', label: '笔记本', width: 1280, height: 800 },
  { id: 'tablet', label: '平板', width: 768, height: 1024 }, { id: 'phone', label: '手机 · 390', width: 390, height: 844 }, { id: 'compact', label: '手机 · 360', width: 360, height: 800 },
];
const draft = ref({ name: '响应式页面检查', url: '{{baseUrl}}/', devices: ['desktop', 'tablet', 'phone'], engines: ['chromium'], settleMs: 500, requiredSelector: '' });
const sourceId = ref(''), presetId = ref(''), selected = ref<DeviceResult>(), image = ref('');
const { job, result, busy, error, run, cancel, loadHistory } = useExecution<CompatResult>('compat');
const passed = computed(() => result.value?.results.filter(r => r.passed).length || 0);
const issues = computed(() => result.value?.results.reduce((n, r) => n + r.issues.length, 0) || 0);
function source() { const item = data.uiCases.find(c => c.id === sourceId.value); if (item) { draft.value.url = item.url; draft.value.name = item.name + ' · 兼容性'; } }
function save() { presetId.value = savePreset('compat', draft.value.name, draft.value, presetId.value) || ''; }
function load(payload: typeof draft.value, id: string) { draft.value = clone(payload); presetId.value = id; sourceId.value = ''; }
onMounted(loadCapabilities);
</script>
<template><div class="page lab-page"><div class="page-heading"><div><div class="eyebrow">BROWSER × VIEWPORT MATRIX</div><h1>兼容性测试</h1><p>在真实浏览器内核中检查不同视口，保留页面截图、布局尺寸与加载问题。</p></div><div class="page-actions"><EnvironmentPicker compact /><button class="button" @click="save"><Icon name="save" />保存矩阵</button><button class="button primary" :disabled="busy || !draft.devices.length || !draft.engines.length" @click="run(draft)"><Icon :name="busy ? 'loader' : 'play'" :class="{spin: busy}" />{{ busy ? '正在检测' : '运行检测矩阵' }}</button></div></div><PresetBar kind="compat" @load="load" />
  <section class="card lab-panel compatibility-config"><div class="compatibility-target"><label class="field">检查名称<input v-model="draft.name" aria-label="兼容性检查名称" /></label><label class="field">从 UI 用例载入地址<select v-model="sourceId" aria-label="兼容性来源 UI 用例" @change="source"><option value="">自定义地址</option><option v-for="item in data.uiCases" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="field compatibility-url">页面地址<input v-model="draft.url" aria-label="兼容性目标地址" class="mono" /></label></div><div class="matrix-selection"><div class="engine-selection"><h3>浏览器内核</h3><label v-for="[value,label] in [['chromium','Chromium / Edge'],['firefox','Firefox'],['webkit','WebKit']]" :key="value" :class="{unavailable: !capabilities?.browsers[value]}"><input v-model="draft.engines" type="checkbox" :value="value" :disabled="!capabilities?.browsers[value]" /><span>{{ label }}</span><small>{{ !capabilities ? '检测中' : capabilities.browsers[value] ? '可运行' : '未安装' }}</small></label></div><div class="viewport-selection"><h3>设备视口</h3><div class="device-chips"><label v-for="device in devices" :key="device.id" :class="{selected: draft.devices.includes(device.id)}"><input v-model="draft.devices" type="checkbox" :value="device.id" /><Icon :name="device.width < 500 ? 'compat' : 'ui'" :size="18" /><span><strong>{{ device.label }}</strong><small>{{ device.width }} × {{ device.height }}</small></span></label></div></div></div><div class="compatibility-options"><label class="field">关键元素（可选）<input v-model="draft.requiredSelector" aria-label="兼容性关键元素选择器" placeholder="例如 #app / .main-navigation" /></label><label class="field">页面稳定等待 ms<input v-model.number="draft.settleMs" type="number" min="0" max="3000" aria-label="兼容性稳定等待时间" /></label><p>UI 用例仅提供起始地址，不执行登录步骤。设备使用视口与 UA 模拟，不能替代真机；内核以实际安装的执行器为准。</p></div></section>
  <section class="card lab-panel compatibility-report"><div class="section-title"><div><h2>检测矩阵</h2><p v-if="result" class="executed-target">执行目标：{{ result.url }}</p></div><div class="compatibility-counters"><span>{{ result?.results.length ?? 0 }}/{{ result?.total ?? draft.engines.length * draft.devices.length }} 已完成</span><span class="text-good">{{ result ? passed : '—' }} 通过</span><span>{{ result ? issues : '—' }} 项提示 / 问题</span><button v-if="job && !busy" class="button small" @click="downloadJson(job, `compatibility-${job.id}.json`)">导出证据</button></div></div><ExecutionStatus :job="job" :busy="busy" :error="error" @cancel="cancel" /><div v-if="!result?.results.length" class="device-preview-grid"><div v-for="device in devices.filter(d => draft.devices.includes(d.id))" :key="device.id" class="device-placeholder"><div><Icon :name="device.width < 500 ? 'compat' : 'ui'" :size="29" /><span>等待真实截图</span></div><footer><strong>{{ device.label }}</strong><span>{{ device.width }} × {{ device.height }}</span></footer></div></div><div v-else class="device-preview-grid"><article v-for="item in result.results" :key="item.id" class="device-result"><button class="device-screenshot" :aria-label="`查看 ${item.engine} ${item.label} 截图`" :disabled="!item.screenshot" @click="image = item.screenshot || ''"><img v-if="item.screenshot" :src="item.screenshot" :alt="`${item.engine} ${item.width}×${item.height} 的真实页面截图`" loading="lazy" /><span v-else>页面未能完成截图</span></button><div class="device-result-body"><div class="section-title"><h3>{{ item.label }}</h3><span :class="['badge', item.passed ? 'good' : 'bad']">{{ item.passed ? item.issues.length ? '通过 · 有提示' : '通过' : '发现问题' }}</span></div><p>{{ item.engine }} · {{ item.width }} × {{ item.height }} · HTTP {{ item.status || '—' }}</p><ul v-if="item.issues.length"><li v-for="(issue,index) in item.issues.slice(0,3)" :key="index" :class="issue.severity === 'error' ? 'text-bad' : 'muted'">{{ issue.message }}</li></ul><p v-else class="text-good help">本次未发现溢出、脚本或资源加载错误。</p><button class="text-button" @click="selected = item">查看检查证据<Icon name="arrow" :size="13" /></button></div></article></div></section><ExecutionHistory kind="compat" @select="loadHistory" />
  <Modal v-if="selected" :title="`${selected.engine} · ${selected.label} 检查证据`" wide @close="selected = undefined"><div class="evidence-metadata"><span>HTTP {{ selected.status || '—' }}</span><span>视口 {{ selected.width }} × {{ selected.height }}</span><span>{{ selected.durationMs }} ms</span></div><p class="muted help">{{ selected.title }}</p><div v-if="selected.dimensions" class="dimensions-evidence"><span>布局宽度 <strong>{{ selected.dimensions.clientWidth }}px</strong></span><span>内容宽度 <strong>{{ selected.dimensions.scrollWidth }}px</strong></span><span>页面高度 <strong>{{ selected.dimensions.pageHeight }}px</strong></span></div><h3 class="small-heading">问题与提示</h3><p v-if="!selected.issues.length" class="muted help">当前检查项未发现问题。</p><p v-for="(issue,index) in selected.issues" :key="index" class="evidence-issue">{{ issue.message }}</p><template v-if="selected.overflowElements.length"><h3 class="small-heading">可能导致溢出的元素</h3><pre class="failure-stack">{{ JSON.stringify(selected.overflowElements, null, 2) }}</pre></template><template v-if="selected.consoleErrors.length"><h3 class="small-heading">脚本与控制台错误</h3><pre v-for="(text,index) in selected.consoleErrors" :key="index" class="failure-stack">{{ text }}</pre></template><template v-if="selected.networkErrors.length"><h3 class="small-heading">资源请求失败</h3><pre v-for="(item,index) in selected.networkErrors" :key="index" class="failure-stack">{{ item.error }} · {{ item.url }}</pre></template><template #footer><a v-if="selected.screenshot" :href="selected.screenshot" download class="button">下载截图</a><button class="button primary" @click="selected = undefined">关闭</button></template></Modal>
  <Modal v-if="image" title="真实浏览器截图" wide @close="image = ''"><img :src="image" alt="兼容性检测的完整页面截图" class="screenshot-preview" /><template #footer><a :href="image" download class="button">下载原图</a><button class="button primary" @click="image = ''">关闭</button></template></Modal>
</div></template>
